/** Bounded, composition-owned cache shared by sibling tiles; no process-global product data. */
class SbValueMeasureCache {
    private data class Key(
        val texts: List<String>, val width: Int, val style: TextStyle,
        val density: Float, val fontScale: Float, val resolver: FontFamily.Resolver,
        val direction: LayoutDirection,
    )
    private val sizes = linkedMapOf<Key, IntSize>()
    private val words = linkedMapOf<Key, Int>()

    internal fun wrappingStyle(
        text: String, width: Int, style: TextStyle, density: Float, fontScale: Float,
        resolver: FontFamily.Resolver, direction: LayoutDirection, measurer: TextMeasurer,
    ): TextStyle {
        val key = Key(listOf(text), Constraints.Infinity, style, density, fontScale, resolver, direction)
        val widest = words[key] ?: run {
            val measured = text.split(Regex("\\s+")).filter { it.isNotEmpty() }.maxOfOrNull {
                measurer.measure(it, style, softWrap = false, maxLines = 1).size.width
            } ?: 0
            if (words.size >= 32) words.remove(words.keys.first())
            words[key] = measured
            measured
        }
        // D130: a word that misses only because of the dark letter spacing (D44) drops that spacing instead of hyphenating
        if (widest > width && style.letterSpacing != 0.em) {
            val flat = style.copy(letterSpacing = 0.em)
            val flatKey = Key(listOf(text), Constraints.Infinity, flat, density, fontScale, resolver, direction)
            val flatWidest = words[flatKey] ?: run {
                val measured = text.split(Regex("\\s+")).filter { it.isNotEmpty() }.maxOfOrNull {
                    measurer.measure(it, flat, softWrap = false, maxLines = 1).size.width
                } ?: 0
                if (words.size >= 32) words.remove(words.keys.first())
                words[flatKey] = measured
                measured
            }
            if (flatWidest <= width) return flat.copy(lineBreak = androidx.compose.ui.text.style.LineBreak.Simple,
                hyphens = androidx.compose.ui.text.style.Hyphens.None)
        }
        val oversized = widest > width
        return style.copy(lineBreak = if (oversized) androidx.compose.ui.text.style.LineBreak.Heading
                else androidx.compose.ui.text.style.LineBreak.Simple,
            hyphens = if (oversized) androidx.compose.ui.text.style.Hyphens.Auto
                else androidx.compose.ui.text.style.Hyphens.None)
    }
    internal var measureCalls: Int = 0
        private set

    internal fun maximum(
        texts: List<String>, width: Int, style: TextStyle, density: Float, fontScale: Float,
        resolver: FontFamily.Resolver, direction: LayoutDirection, measurer: TextMeasurer,
    ): IntSize? {
        if (texts.isEmpty()) return null
        val key = Key(texts, width, style, density, fontScale, resolver, direction)
        sizes[key]?.let { return it }
        var maxWidth = 0
        var maxHeight = 0
        for (text in texts) {
            measureCalls++
            val size = if (width == Constraints.Infinity) {
                measurer.measure(text, style, softWrap = false, maxLines = 1).size
            } else {
                measurer.measure(text, wrappingStyle(text, width, style, density, fontScale, resolver, direction, measurer),
                    constraints = Constraints(maxWidth = width)).size
            }
            maxWidth = maxOf(maxWidth, size.width)
            maxHeight = maxOf(maxHeight, size.height)
        }
        if (sizes.size >= 32) sizes.remove(sizes.keys.first())
        return IntSize(maxWidth, maxHeight).also { sizes[key] = it }
    }
}

/** SebaroAppTheme shares this across its tiles. An app may hoist/provide one across multiple roots. */
val LocalSbValueMeasureCache = staticCompositionLocalOf<SbValueMeasureCache?> { null }

/** The state a value tile shows under its number (D105 (33), spec/02 §3.30). */
enum class SbValueState { Plain, Kept, Struck }

