/**
 * A value tile (spec/02 §3.30; D105 (33)): [value] large (display, tabular figures) in a frame tile (1 dp
 * borderStrong, radius control, no fill, at least 64 × 64 dp); under it the state as glyph and word in text, caption,
 * without colour: „behalten“ (check) and „gestrichen“ (close); the plain tile keeps that line's room, so holding moves
 * nothing. [onToggle] makes it a check box for TalkBack (held = checked); [name] is read first („Würfel 3: 5,
 * behalten“). [enabled] = false: the value cannot be held now (a struck one).
 * [valueAlpha] affects only the number. [spokenValue] hides interim values from accessibility. [minValueText]
 * reserves the measured width up to 128 dp; longer values wrap and grow vertically (D99).
 * [holdSize] reserves the maximum width and wrapped height of [minValueTexts] plus [minValueText], measured
 * at the value's available inner width. Keep candidates constant during the roll and cover every possible value.
 * The list is ignored at rest; false restores the resting shortcut's 128 dp minimum cap.
 * Value padding is space.s3 plus the frame stroke (12 dp clear inside the frame): the Column's space.s1
 * plus the value Box's space.s2 and borderWidth.control. Both measuring paths and wrapping use that inner width.
 * [spokenState] supplies the final audible state while the visible line stays plain (D123); no timeline runs here.
 */
@Composable
fun SbValueTile(
    value: String,
    modifier: Modifier = Modifier,
    state: SbValueState = SbValueState.Plain,
    name: String? = null,
    onToggle: ((Boolean) -> Unit)? = null,
    enabled: Boolean = true,
    valueAlpha: Float = 1f,
    spokenValue: String? = null,
    minValueText: String? = null,
    spokenState: SbValueState? = null,
    holdSize: Boolean = false,
    minValueTexts: List<String> = emptyList(),
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val word = when (state) {
        SbValueState.Kept -> m.valueKept
        SbValueState.Struck -> m.valueStruck
        SbValueState.Plain -> null
    }
    val glyph = when (state) {
        SbValueState.Kept -> SebaroIcons.Outline16.Check
        SbValueState.Struck -> SebaroIcons.Outline16.Close
        SbValueState.Plain -> null
    }
    val audibleValue = spokenValue ?: value
    val audibleState = when (spokenState ?: state) {
        SbValueState.Kept -> m.valueKept
        SbValueState.Struck -> m.valueStruck
        SbValueState.Plain -> null
    }
    val spoken = listOfNotNull(if (name != null) "$name: $audibleValue" else audibleValue, audibleState).joinToString(", ")
    val measurer = rememberTextMeasurer()
    val density = LocalDensity.current
    val valueStyle = ty.display.copy(fontFeatureSettings = ty.numeric.fontFeatureSettings,
        hyphens = androidx.compose.ui.text.style.Hyphens.None,
        lineBreak = androidx.compose.ui.text.style.LineBreak.Simple)
    val valueSize = remember(minValueText, valueStyle, density.density, density.fontScale,
        LocalFontFamilyResolver.current, LocalLayoutDirection.current) {
        minValueText?.let { measurer.measure(it, valueStyle, softWrap = false, maxLines = 1).size }
    }
    val candidates = remember(minValueTexts, minValueText) { minValueTexts.toList() + listOfNotNull(minValueText) }
    val measures = LocalSbValueMeasureCache.current ?: remember { SbValueMeasureCache() }
    val resolver = LocalFontFamilyResolver.current
    val direction = LocalLayoutDirection.current
    fun maximum(width: Int) = measures.maximum(candidates, width, valueStyle, density.density,
        density.fontScale, resolver, direction, measurer)
    val heldWidth = if (holdSize) maximum(Constraints.Infinity)?.width else null
    val widestState = listOf(m.valueKept, m.valueStruck).maxBy {
        measurer.measure(it, ty.caption, softWrap = false, maxLines = 1).size.width
    }
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val shape = RoundedCornerShape(t.radius.control)
    Column(
        modifier
            .sbFocusRing(interaction, t.radius.control)
            .widthIn(min = t.space.s16)
            .heightIn(min = t.space.s16)
            .clip(shape)
            .background(if (pressed) c.pressedFill else if (hovered && onToggle != null) c.hoverFill else Color.Transparent, shape)
            .border(t.borderWidth.control, c.borderStrong, shape)
            .then(
                if (onToggle != null) {
                    Modifier.toggleable(
                        value = state == SbValueState.Kept,
                        interactionSource = interaction,
                        indication = null,
                        enabled = enabled,
                        role = Role.Checkbox,
                        onValueChange = onToggle,
                    )
                } else {
                    Modifier
                },
            )
            .semantics(mergeDescendants = true) { contentDescription = spoken }
            .padding(horizontal = t.space.s1, vertical = t.space.s2),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(t.space.s1, Alignment.CenterVertically),
    ) {
        BoxWithConstraints(
            Modifier.padding(horizontal = t.space.s2 + t.borderWidth.control).then(
                if (heldWidth != null) Modifier.sbLayout { measurable, constraints ->
                    // Column and value-Box padding have already removed both inset layers.
                    val width = heldWidth.coerceIn(constraints.minWidth, constraints.maxWidth)
                    val height = maximum(width)!!.height.coerceIn(constraints.minHeight, constraints.maxHeight)
                    val placeable = measurable.measure(constraints.copy(
                        minWidth = width, maxWidth = width, minHeight = height))
                    layout(placeable.width, placeable.height) { placeable.placeRelative(0, 0) }
                } else if (valueSize != null) with(density) {
                    Modifier.widthIn(min = minOf(valueSize.width.toDp(), 128.dp))
                } else Modifier,
            ),
            contentAlignment = Alignment.Center,
        ) {
            Text(
                value,
                style = measures.wrappingStyle(value, constraints.maxWidth, valueStyle, density.density,
                    density.fontScale, resolver, direction, measurer),
                color = c.text,
                softWrap = true,
                textAlign = TextAlign.Center,
                modifier = Modifier.clearAndSetSemantics { }.alpha(valueAlpha.coerceIn(0f, 1f)),
            )
        }
        // Reserve one measured longest state line, not two separate hidden rows.
        Box(Modifier.clearAndSetSemantics { }, contentAlignment = Alignment.Center) {
            SbValueStateLine(widestState, SebaroIcons.Outline16.Check, Modifier.alpha(0f))
            if (word != null && glyph != null) SbValueStateLine(word, glyph)
        }
    }
}

