/** The glyph and word under a value tile's number, in text, caption, without colour. */
@Composable
private fun SbValueStateLine(word: String, glyph: ImageVector, modifier: Modifier = Modifier) {
    val t = SebaroTheme.tokens
    Row(
        modifier,
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s1),
    ) {
        Icon(glyph, contentDescription = null, tint = SebaroTheme.colors.text, modifier = Modifier.size(t.size.iconSm))
        Text(word, style = SebaroTheme.typography.caption, color = SebaroTheme.colors.text)
    }
}
